  "knowledge": "socialcommunity.community_engagement.content_creation.contqualrate",
  "description": "Explains content quality rating standards and classification",
  "definition": "Content quality rating (contqualrate) ranges from 0-10.0: 0-3.9 points indicate low-quality content (potentially violating rules or poor quality); 4.0-6.9 points represent medium-quality content (meeting basic platform standards); 7.0-8.9 points indicate high-quality content (well-produced and creative); 9.0-10.0 points represent premium content (platform recommendation level). Quality ratings affect content recommendations, exposure, and creator incentives."
}

{
  "id": 22,
  "knowledge": "Social Amplifier",
  "description": "Identifies fans who significantly extend idol content reach",
  "definition": "A fan with follcount > 500, SIM > 2.0, and viralcont \u2265 1, representing users who effectively spread idol content through their substantial social networks."
}

{
  "id": 14,
  "knowledge": "Social Influence Multiplier (SIM)",
  "description": "Calculates how much a fan amplifies content through their social network",
  "definition": "SIM = \\left(\\frac{follcount}{100}\\right) \\times (engrate \\times 2) \\times (viralcont + 1) \\times 0.5, \\text{ reflecting the fan's ability to spread content through their network based on their following, engagement level, and history of creating viral content.}"
}

